function renderR5(){const b=bank().R5,id=state.runit.R5,t=(b.topics||[]).find(x=>x.topic_id===id),items=(b.items||[]).filter(x=>x.topic_id===id).sort((a,z)=>a.heading_position-z.heading_position);if(!t)return `<section class="card">Không có dữ liệu R5.</section>`;const headingIds=items.map(x=>x.id),hkey=orderKey("R5headings"),hord=getOrder(hkey,headingIds),hm=new Map(items.map(x=>[x.id,x]));const pids=items.map(x=>x.id),pkey=orderKey("R5paras"),pord=getOrder(pkey,pids);return `<section class="card"><div class="head"><h2>Reading Part 5 · ${esc(t.title_en_teacher)}</h2><div class="sub">7 headings SOURCE · 7 paragraphs GENERATED_PRACTICE</div></div><div class="note generated"><b>Quan trọng:</b> nguồn canonical không có 7 paragraph đầy đủ. Heading/key bên dưới là SOURCE; các paragraph luyện tập được sinh riêng và luôn gắn nhãn GENERATED_PRACTICE.</div><div><b>Heading pool:</b><div class="heading-pool">${hord.map((hid,i)=>`<span class="heading-chip">${i+1}. ${esc(hm.get(hid).heading_en_teacher)}</span>`).join("")}</div></div>${pord.map((pid,n)=>{const x=hm.get(pid);return `<article class="r5para" data-q="${esc(pid)}"><div class="qhead"><div class="number">Paragraph ${n+1}</div>${provBadge("GENERATED_PRACTICE")}</div><p>${esc(x.practice_paragraph_en)}</p><div class="toolbar"><button class="btn ghost small" data-action="speak-r5" data-id="${esc(pid)}">🔊 Đọc</button></div><select class="select r5ans" data-id="${esc(pid)}" style="width:100%;margin-top:8px"><option value="">-- Chọn heading --</option>${hord.map(hid=>`<option value="${esc(hid)}">${esc(hm.get(hid).heading_en_teacher)}</option>`).join("")}</select><div class="toolbar"><button class="btn key" data-action="toggle" data-target="key-${esc(pid)}">🔑 Hiện Key</button><button class="btn" data-action="check-r5-item" data-id="${esc(pid)}">✓ Chấm câu</button></div><div id="key-${esc(pid)}" class="keybox hidden"><div class="key-answer">${esc(x.heading_en_teacher)}</div><div>${esc(x.heading_vi_teacher)}</div><div><b>Memory token:</b> ${esc(x.memory_token)} · <b>Chain:</b> ${esc(x.mnemonic_chain)}</div><div class="evidence">Giải thích paragraph luyện tập: ${esc(x.practice_paragraph_vi)}</div></div><div id="fb-${esc(pid)}"></div></article>`}).join("")}<div class="sticky-actions toolbar space"><span class="counter">R5 · Source paragraphs = 0; practice paragraphs = 7</span><div class="toolbar"><button class="btn key" data-action="show-all-keys">🔑 Hiện tất cả Key</button><button class="btn" data-action="check-r5-all">✓ Chấm bài</button></div></div></section>`}
function answerL3(x){let a=x.answer||x.correct||x.answer_text||x.key_vi?.answer_text||"";a=String(a).toLowerCase();if(a.includes("man")||a==="m"||a==="1")return"M";if(a.includes("woman")||a==="w"||a==="2")return"W";if(a.includes("both")||a==="b"||a==="0")return"B";return String(x.code_digit??x.key_vi?.code_digit??"")==="1"?"M":String(x.code_digit??x.key_vi?.code_digit??"")==="2"?"W":"B"}
